var SPINNERS={
  ring:{name:'旋转圆环', kids:0, css:'.spinner{width:SIZEpx;height:SIZEpx;border:3px solid rgba(0,0,0,.12);border-top-color:COLOR;border-radius:50%;animation:spinner-spin .8s linear infinite;}\n@keyframes spinner-spin{to{transform:rotate(360deg);}}'},
  dots:{name:'三点跳动', kids:3, css:'.spinner{display:inline-flex;gap:6px;align-items:center;}\n.spinner > i{width:SIZEpx;height:SIZEpx;border-radius:50%;background:COLOR;animation:spinner-bounce .9s ease-in-out infinite;}\n.spinner > i:nth-child(2){animation-delay:.15s;}\n.spinner > i:nth-child(3){animation-delay:.3s;}\n@keyframes spinner-bounce{0%,80%,100%{transform:scale(.4);opacity:.4;}40%{transform:scale(1);opacity:1;}}'},
  pulse:{name:'脉冲圆环', kids:0, css:'.spinner{width:SIZEpx;height:SIZEpx;border-radius:50%;background:COLOR;animation:spinner-pulse 1.2s ease-in-out infinite;}\n@keyframes spinner-pulse{0%{transform:scale(.3);opacity:1;}100%{transform:scale(1);opacity:0;}}'}
};
function spinnerCss(kind, opts){
  opts=opts||{}; var k=kind||'ring';
  var S=SPINNERS[k];
  if(!S) return {ok:false, reason:'unknown spinner'};
  var size=opts.size!=null?opts.size:36;
  var color=opts.color||'#5E6AD2';
  var css=S.css.replace(/SIZE/g,String(size)).replace(/COLOR/g,color);
  return {ok:true, name:S.name, css:css, kind:k, kids:S.kids};
}

var EXPORTS={spinnerCss:spinnerCss,SPINNERS:SPINNERS};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpinnerForgePure = EXPORTS; }
